// *** IR Dump After InlineElementals ***
module @_QMmatrix_ops {
  func.func @_QPmatrix_ops(
      %arg0: !fir.ref<!fir.array<?x?xf32>> {fir.bindc_name = "c", fir.inout},
      %arg1: !fir.ref<!fir.array<?x?xf32>> {fir.bindc_name = "a", fir.in},
      %arg2: !fir.ref<!fir.array<?x?xf32>> {fir.bindc_name = "b", fir.in},
      %arg3: !fir.ref<i32>                 {fir.bindc_name = "n", fir.in},
      %arg4: !fir.ref<i32>                 {fir.bindc_name = "m", fir.in},
      %arg5: !fir.ref<i32>                 {fir.bindc_name = "k", fir.in}
  ) {
    %n = fir.load %arg3 : !fir.ref<i32>
    %m = fir.load %arg4 : !fir.ref<i32>
    %k = fir.load %arg5 : !fir.ref<i32>
    %n_i = fir.convert %n : (i32) -> index
    %m_i = fir.convert %m : (i32) -> index
    %k_i = fir.convert %k : (i32) -> index

    %shape_a = fir.shape %n_i, %m_i : (index, index) -> !fir.shape<2>
    %shape_b = fir.shape %m_i, %k_i : (index, index) -> !fir.shape<2>
    %shape_c = fir.shape %n_i, %k_i : (index, index) -> !fir.shape<2>

    // Embox arguments into descriptors for the runtime ABI
    %a_box = fir.embox %arg1(%shape_a) : (!fir.ref<!fir.array<?x?xf32>>, !fir.shape<2>) -> !fir.box<!fir.array<?x?xf32>>
    %b_box = fir.embox %arg2(%shape_b) : (!fir.ref<!fir.array<?x?xf32>>, !fir.shape<2>) -> !fir.box<!fir.array<?x?xf32>>

    // Allocate result descriptor on stack
    %result_desc = fir.alloca !fir.box<!fir.heap<!fir.array<?x?xf32>>>
    fir.store %0 to %result_desc : !fir.ref<!fir.box<!fir.heap<!fir.array<?x?xf32>>>>

    // MATMUL → runtime call
    fir.call @_FortranAMatmul(%result_desc, %a_box, %b_box, ...) : (...) -> ()

    // Load result and store to c
    %result_val = fir.load %result_desc : !fir.ref<!fir.box<!fir.heap<!fir.array<?x?xf32>>>>
    %result_ptr = fir.box_addr %result_val : (!fir.box<!fir.heap<!fir.array<?x?xf32>>>) -> !fir.heap<!fir.array<?x?xf32>>

    // Copy result into c (fir.array_merge_store equivalent for heap arrays)
    %c_box = fir.embox %arg0(%shape_c) : (!fir.ref<!fir.array<?x?xf32>>, !fir.shape<2>) -> !fir.box<!fir.array<?x?xf32>>
    fir.call @_FortranAAssign(%c_box, %result_val, ...) : (...) -> ()

    // Free the temporary result
    %heap_ptr = fir.box_addr %result_val : (...) -> !fir.heap<!fir.array<?x?xf32>>
    fir.freemem %heap_ptr : !fir.heap<!fir.array<?x?xf32>>
    return
  }
}
