      %arg2: !fir.ref<!fir.array<?x?xf32>> {fir.bindc_name = "b", fir.in},
      %arg3: !fir.ref<i32>, %arg4: !fir.ref<i32>, %arg5: !fir.ref<i32>
  ) {
    %n = fir.load %arg3 : !fir.ref<i32>
    %m = fir.load %arg4 : !fir.ref<i32>
    %k = fir.load %arg5 : !fir.ref<i32>
    %n_i = fir.convert %n : (i32) -> index
    %m_i = fir.convert %m : (i32) -> index
    %k_i = fir.convert %k : (i32) -> index

    %sha_a = fir.shape %n_i, %m_i : (index, index) -> !fir.shape<2>
    %sha_b = fir.shape %m_i, %k_i : (index, index) -> !fir.shape<2>
    %sha_c = fir.shape %n_i, %k_i : (index, index) -> !fir.shape<2>

    %a:2 = hlfir.declare %arg1(%sha_a) {fortran_attrs = #fir.var_attrs<intent_in>, uniq_name = "_QFmatrix_opsEa"}
               : (...) -> (!fir.box<!fir.array<?x?xf32>>, !fir.ref<!fir.array<?x?xf32>>)
    %b:2 = hlfir.declare %arg2(%sha_b) {fortran_attrs = #fir.var_attrs<intent_in>, uniq_name = "_QFmatrix_opsEb"}
               : (...) -> (!fir.box<!fir.array<?x?xf32>>, !fir.ref<!fir.array<?x?xf32>>)
    %c:2 = hlfir.declare %arg0(%sha_c) {fortran_attrs = #fir.var_attrs<intent_out>, uniq_name = "_QFmatrix_opsEc"}
               : (...) -> (!fir.box<!fir.array<?x?xf32>>, !fir.ref<!fir.array<?x?xf32>>)

    // MATMUL: HLFIR represents it as hlfir.matmul before lowering
    // This is a TRANSFORMATIONAL op — produces a value-typed heap expression
    %matmul_result = hlfir.matmul %a#0, %b#0
                         : (!fir.box<!fir.array<?x?xf32>>, !fir.box<!fir.array<?x?xf32>>)
                        -> !hlfir.expr<?x?xf32>

    // Assign the heap expression into c
    hlfir.assign %matmul_result to %c#0
        : !hlfir.expr<?x?xf32>, !fir.box<!fir.array<?x?xf32>>

    // Release temporary heap storage
    hlfir.destroy %matmul_result : !hlfir.expr<?x?xf32>
